// ART-BIBLE §§3–4, 8, 10: stepped cool trails, warm cores, no blur or flashes.
(()=>{'use strict';const A=ButtonwoodArt,P=A.palette;
A.paintMeteor=function(g,x,y,age,seed,hot=false,opacity=1,direction=1,size=4){const tail=hot?65:46+seed%35,slope=hot?10:.40;const r=(xx,yy,w,h,k,a=1)=>{g.globalAlpha=a*opacity;g.fillStyle=P[k];g.fillRect(Math.round(xx),Math.round(yy),w,h)};g.save();g.imageSmoothingEnabled=false;for(let i=tail;i>0;i--){const a=(1-i/tail)*.8;r(x-i/slope*direction,y-i,3,2,hot?'coralShade':'waterShade',a);if(i<tail*.7)r(x-i/slope*direction,y-i,2,1,hot?'coral':'waterLight',a);if(i%8===0)r(x-i/slope*direction-3,y-i+3,1,1,hot?'gold':'creamLight',a*.55)}if(hot){const radius=size===6?15:9;for(let yy=-radius;yy<=radius;yy++){const span=Math.floor(Math.sqrt(radius*radius-yy*yy));r(x-span,y+yy,span*2+1,1,'coralShade');if(span>2)r(x-span+2,y+yy,span*2-3,1,yy>radius*.35?'woodShade':'coral');if(Math.abs(yy)<radius*.7&&span>4)r(x-span*.55,y+yy,Math.max(1,Math.floor(span)),1,'gold');if(Math.abs(yy)<radius*.35)r(x-span*.25,y+yy,Math.max(1,Math.floor(span*.55)),1,'creamLight')}for(let i=0;i<4;i++)r(x+(i-2)*4,y-radius-5-(seed+i)%7,3,8,'coral');r(x-radius+3,y+radius-5,5,3,'ink')}else{r(x-2,y-1,5,3,'waterLight');r(x-1,y-1,3,3,'creamLight');r(x,y,1,1,'creamLight')}g.restore()};
A.paintMeteorImpact=function(g,x,y,age,seed,size=4){g.save();if(size&&age<360){const quiet=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches,radius=size*16,progress=quiet?1:Math.min(1,age/140+.25),tiles=size;g.globalAlpha=Math.max(0,(1-age/420)*.72);for(let yy=0;yy<tiles;yy++)for(let xx=0;xx<tiles;xx++){const dx=xx+.5-tiles/2,dy=yy+.5-tiles/2;if(dx*dx+dy*dy>(tiles/2)**2)continue;const px=Math.round(x+(xx-tiles/2)*32*progress),py=Math.round(y+(yy-tiles/2)*32*progress),w=Math.ceil(32*progress);g.fillStyle=P[(xx+yy)%3===0?'gold':'coral'];g.fillRect(px,py,w,w);g.fillStyle=P.creamLight;g.fillRect(px+2,py+2,Math.max(1,w-4),Math.max(1,w-4));}g.globalAlpha=Math.max(0,1-age/360);g.fillStyle=P.gold;g.fillRect(Math.round(x-radius*progress),Math.round(y-2),Math.round(radius*progress*2),3)}for(let i=0;i<28;i++){const angle=(i*2.4+seed)*Math.PI/5,dist=age*.08*(1+i%3),xx=Math.round(x+Math.cos(angle)*dist),yy=Math.round(y+Math.sin(angle)*dist+age*age*.000035);g.globalAlpha=Math.max(0,1-age/900);g.fillStyle=P[i%4===0?'creamLight':i%4===1?'gold':i%4===2?'coral':'woodShade'];g.fillRect(xx,yy,i%4===0?3:2,i%4===0?3:2)}g.restore()};
A.paintMeteorShower=function(g,o,rect){const e=A.meteorSkyState;if(!e?.active)return;const seconds=e.elapsed/1000,width=o.width,ground=o.ground,camY=o.camY||0,span=Math.max(100,ground+camY);g.save();for(let i=0;i<270;i++){const born=2+i*.32+(i*37%13)/13,age=seconds-born,duration=1.6+(i*19%10)/10;if(age<0||age>duration)continue;const p=age/duration,x=width*((i*79%89)/100)+p*(220+i%140),y=Math.min(o.height,span)*(.12+(i*41%49)/100)+p*110+camY*.008;if(y<0||y>=ground)continue;g.save();g.beginPath();g.rect(0,0,width,Math.max(0,Math.min(o.height,ground)));g.clip();A.paintMeteor(g,x,y,age,i+e.seed,false,Math.min(1,p/.12,(1-p)/.25));g.restore()}g.restore()};
})();
